import json
with open('contract_ground_truth') as f:
    total_segments = 0
    multi = 0
    for line in f:
        rec = json.loads(line)
        intervals = {}
        for cat, info in rec['gold'].items():
            if not info['is_impossible']:
                for s in info['spans']:
                    intervals.setdefault(cat, []).append((s[0], s[1]))
        # build points
        points = set()
        for cat, lst in intervals.items():
            for a,b in lst:
                points.add(a)
                points.add(b+1)
        points = sorted(points)
        for i in range(len(points)-1):
            p = points[i]
            q = points[i+1]-1
            cats = []
            for cat, lst in intervals.items():
                for a,b in lst:
                    if a <= p and b >= q:
                        cats.append(cat)
                        break
            total_segments += 1
            if len(cats) > 1:
                multi += 1
    print('segments', total_segments, 'multi', multi)
