function renderContract(id) {
  const text = await fetch('contract_text/'+id+'.txt').then(r=>r.text());
  const gold = groundTruth[id];
  const present = [];
  for (const [cat, info] of Object.entries(gold)) {
    if (!info.is_impossible) present.push({cat, spans: info.spans});
  }
  // build categories list
  // build intervals for filter
  const filterCat = currentFilter; // null for all
  const intervals = [];
  for (const p of present) {
    if (!filterCat || filterCat === p.cat) {
      for (const s of p.spans) {
        intervals.push({start: s[0], end: s[1], cat: p.cat});
      }
    }
  }
  // sort intervals by start
  intervals.sort((a,b)=>a.start-b.start);
  // build points
  const points = new Set();
  for (const iv of intervals) {
    points.add(iv.start);
    points.add(iv.end + 1);
  }
  const sortedPoints = Array.from(points).sort((a,b)=>a-b);
  let html = '<pre>';
  for (let i = 0; i < sortedPoints.length - 1; i++) {
    const s = sortedPoints[i];
    const e = sortedPoints[i+1] - 1;
    const segment = text.slice(s, sortedPoints[i+1]);
    // find covering intervals
    const covering = intervals.filter(iv => iv.start <= s && iv.end >= e);
    if (covering.length > 0) {
      const first = covering[0];
      const title = covering.map(iv => iv.cat).join(', ');
      html += `<span class="highlight" style="background:${getColor(first.cat)}; border-radius:2px;" title="${escapeHtml(title)}">${escapeHtml(segment)}</span>`;
    } else {
      html += escapeHtml(segment);
    }
  }
  html += '</pre>';
  document.getElementById('text').innerHTML = html;
}
